            mensagemmodalincluirevento.insertAdjacentHTML('afterbegin', mensagemHTML);
          } catch (e) {
            console.error(e);
          }
        }

        // Take over form submission
        form.addEventListener("submit", (event) => {
          event.preventDefault();
          sendData();
