<script>

    let requerlogin = '';
    let acao = '';
    let filtro = '';
    let parametros = '';

    const modalLogin = document.getElementById('modalLogin');

    modalLogin.addEventListener('show.mdb.modal', (e) => {
      if (typeof e.relatedTarget !== 'undefined') {
          // Button that triggered the modal
          const button = e.relatedTarget;
          // Extract info from data-mdb-* attributes
          acao = button.getAttribute('data-mdb-acao') || '';
      }
    });

    function handleCredentialResponse(response) {
        console.log('Google onSignIn');
        let urlRedirect = '/en/event/2026-live-run-xp-sao-paulo-2026-iiiiiiii/';

        const audienceQuery = '';
        let urlParams = audienceQuery;
        if (requerlogin) {
            urlParams += '&requerlogin=' + requerlogin;
        }
        if (acao) {
            urlParams += '&acao=' + acao;
        }
        if (filtro) {
            urlParams += '&filtro=' + filtro;
        }
        if (parametros) {
            urlParams += '&parametros=' + parametros;
        }
        if (urlParams) {
            // Preserve an existing query and append before an optional fragment.
            const fragmentAt = urlRedirect.indexOf('#');
            const fragment = fragmentAt < 0 ? '' : urlRedirect.slice(fragmentAt);
            if (fragmentAt >= 0) urlRedirect = urlRedirect.slice(0, fragmentAt);
            const queryAt = urlRedirect.indexOf('?');
            if (audienceQuery && queryAt >= 0) {
                const existingQuery = new URLSearchParams(urlRedirect.slice(queryAt + 1));
                Array.from(existingQuery.keys()).forEach(key => {
                    if (['utm_source', 'utm_medium', 'utm_campaign', 'utm_content'].includes(key.toLowerCase())) existingQuery.delete(key);
                });
                const preservedQuery = existingQuery.toString();
                urlRedirect = urlRedirect.slice(0, queryAt) + (preservedQuery ? '?' + preservedQuery : '');
            }
            urlRedirect += (urlRedirect.includes('?') ? '&' : '?') + urlParams.replace(/^&/, '') + fragment;
        }
        urlRedirect = encodeURIComponent(urlRedirect);

        window.location.href = '/en/event/2026-live-run-xp-sao-paulo-2026-iiiiiiii/?action=googlesignin&credential=' + response.credential + '&redirect=' + urlRedirect;

    }

    function signOut() {
        google.accounts.id.disableAutoSelect();
        console.log('User signed out.');
        window.location.href = '/?action=googlesignout';
        /*var auth2 = gapi.auth2.getAuthInstance();
        auth2.signOut().then(function () {
            console.log('User signed out.');
            window.location.href = '/perfil/?action=googlesignout';
        });*/
    }

</script>





