<script>
    const modalCupomFoco = document.getElementById('modal_cupom_foco');
    modalCupomFoco.addEventListener('show.mdb.modal', (e) => {
        $('#copiaMsg').text(cupomFocoCopyLabel);
        // Button that triggered the modal
        const button = e.relatedTarget;
        // Extract info from data-mdb-* attributes
        const valorBadge = button.getAttribute('data-mdb-valor-badge');
        const complementoBadge = button.getAttribute('data-mdb-complemento-badge');
        const numeroPeito = button.getAttribute('data-mdb-numero-peito');
        // Update the modal's content.
        const linkFoco = document.getElementById("linkFoco");
        const galleryListShell = document.getElementById('focoGalleryListShell');
        const galleryList = document.getElementById('focoGalleryList');
        const galleriesRaw = button.getAttribute('data-mdb-foco-galleries') || '';

        const escapeHtml = (value) => {
            const wrapper = document.createElement('span');
            wrapper.textContent = value || '';
            return wrapper.innerHTML;
        };

        let focoGalleries = [];
        if (galleriesRaw) {
            try {
                focoGalleries = JSON.parse(galleriesRaw);
            } catch (error) {
                focoGalleries = [];
            }
        }

        galleryList.innerHTML = '';
        galleryListShell.classList.add('d-none');
        linkFoco.classList.remove('d-none');

        if (focoGalleries.length > 1) {
            linkFoco.classList.add('d-none');
            galleryListShell.classList.remove('d-none');
            galleryList.innerHTML = focoGalleries.map((gallery) => {
                const meta = [];
                if (gallery.date) {
                    meta.push('<span><i class="fa-regular fa-calendar"></i>' + escapeHtml(gallery.date) + '</span>');
                }
                if (gallery.location) {
                    meta.push('<span><i class="fa-solid fa-location-dot"></i>' + escapeHtml(gallery.location) + '</span>');
                }

                return '<div class="foco-gallery-item">' +
                    '<div class="foco-gallery-title">' + escapeHtml(gallery.name || 'Foco Radical') + '</div>' +
                    (meta.length ? '<div class="foco-gallery-meta">' + meta.join('') + '</div>' : '') +
                    '<a href="' + escapeHtml(gallery.url || 'https://www.focoradical.com.br') + '" target="_blank" rel="noopener" class="btn btn-success w-100 shadow-0">Visualizar minhas fotos&nbsp;&nbsp;<icon class="fa fa-up-right-from-square"></icon></a>' +
                    '</div>';
            }).join('');
        }
        else if (focoGalleries.length === 1 && focoGalleries[0].url) {
            linkFoco.setAttribute("href", focoGalleries[0].url);
        }
        else if (complementoBadge === 'numero') {
            linkFoco.setAttribute("href", "https://www.focoradical.com.br/busca-numero?type=1&competition_id=" + valorBadge + "&number=" + numeroPeito);
        }
        else {
            linkFoco.setAttribute("href", "https://www.focoradical.com.br/prova/" + complementoBadge);
        }

    });
</script>


