            border: 1px solid rgba(51, 51, 51, 0.08);
            border-radius: 10px;
            background-color: #ffffff;
            color: #333333;
            overflow: hidden;
        }

        .event-page-card + .event-page-card {
            margin-top: 0.5rem;
        }

        .event-page-card-body {
            padding: 1rem;
        }

        .event-page-card-body.is-map {
            padding: 0;
        }

        .event-page-card-head {
            padding: 0.95rem 1rem;
            border-bottom: 1px solid rgba(51, 51, 51, 0.08);
            background-color: #efefef;
        }

        .event-page-card-head.is-actionable {
            align-items: center;
            display: flex;
            gap: 0.75rem;
            justify-content: space-between;
        }

        .event-route-embed-trigger {
            align-items: center;
            background: transparent;
            border: 0;
            color: rgba(51, 51, 51, 0.72);
            display: inline-flex;
            flex: 0 0 auto;
            font-size: 0.72rem;
            font-weight: 700;
            gap: 0.32rem;
            padding: 0.2rem 0;
        }

        .event-route-embed-trigger:hover,
        .event-route-embed-trigger:focus-visible {
            color: #111111;
        }

        .event-page-card-title {
            color: #333333;
            font-size: 0.78rem;
            font-weight: 700;
            letter-spacing: 0.06em;
            text-transform: uppercase;
            margin: 0;
        }

        .event-action-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 0.55rem;
        }

        .event-action-grid .full {
            grid-column: 1 / -1;
        }

        .event-action-grid .btn {
            box-shadow: none;
            border-radius: 8px;
        }

        .event-result-action-row {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 0.55rem;
            margin-top: 0.5rem;
        }

        .event-result-action-row .btn {
            margin-top: 0 !important;
        }

        .event-info-copy {
            color: rgba(51, 51, 51, 0.88);
            font-size: 0.92rem;
            line-height: 1.6;
        }

        .event-info-copy a {
            color: #333333;
        }

        .event-linked-video-trigger {
            color: #333333;
            display: grid;
            grid-template-columns: minmax(0, 0.95fr) minmax(0, 1fr);
            text-decoration: none;
        }

        .event-linked-video-trigger:hover {
            color: #333333;
        }

        .event-linked-video-media {
            background-color: #efefef;
            overflow: hidden;
            position: relative;
        }

        .event-linked-video-image,
        .event-linked-video-placeholder {
            aspect-ratio: 16 / 9;
            display: block;
            height: 100%;
            object-fit: cover;
            width: 100%;
        }

        .event-linked-video-placeholder {
            align-items: center;
            background:
                radial-gradient(circle at top right, rgba(250, 177, 32, 0.36), transparent 28%),
                linear-gradient(135deg, #f1f1f1 0%, #e5e5e5 100%);
            color: rgba(51, 51, 51, 0.7);
            display: none;
            font-size: 2rem;
            justify-content: center;
        }

        .event-linked-video-media.is-image-fallback .event-linked-video-image {
            display: none;
        }

        .event-linked-video-media.is-image-fallback .event-linked-video-placeholder {
            display: flex;
        }

        .event-linked-video-play {
            align-items: center;
            display: flex;
            inset: 0;
            justify-content: center;
            pointer-events: none;
            position: absolute;
        }

        .event-linked-video-play span {
            align-items: center;
            background-color: rgba(255, 255, 255, 0.76);
            border-radius: 999px;
            box-shadow: 0 10px 20px rgba(17, 17, 17, 0.08);
            color: rgba(51, 51, 51, 0.72);
            display: flex;
            font-size: 1.05rem;
            height: 52px;
            justify-content: center;
            width: 52px;
        }

        .event-linked-video-copy {
            align-content: center;
            display: grid;
            gap: 0.38rem;
            padding: 1rem;
        }

        .event-linked-video-kicker {
            color: rgba(51, 51, 51, 0.62);
            font-size: 0.72rem;
            font-weight: 700;
            line-height: 1.2;
        }

        .event-linked-video-kicker i {
            color: #fab120;
        }

        .event-linked-video-title {
            color: #333333;
            font-size: 1.02rem;
            font-weight: 700;
            line-height: 1.22;
        }

        .event-linked-video-channel {
            color: rgba(51, 51, 51, 0.72);
            font-size: 0.8rem;
            line-height: 1.3;
        }

        .event-suppliers {
            display: grid;
            gap: 0.45rem;
            margin-top: 0.85rem;
            padding-top: 0.85rem;
            border-top: 1px solid rgba(51, 51, 51, 0.08);
        }

        @media (max-width: 575.98px) {
            .event-linked-video-trigger {
                grid-template-columns: 1fr;
            }

            .event-linked-video-copy {
                padding: 0.88rem;
            }
        }

        .event-supplier-item {
            color: rgba(51, 51, 51, 0.76);
            font-size: 0.82rem;
            line-height: 1.35;
        }

        .event-supplier-item i {
            color: #fab120;
            width: 14px;
        }

        .event-route-shell .nav-tabs {
            border-bottom: 0;
            gap: 0.32rem;
            padding: 0.75rem 0.85rem;
        }

        .event-route-shell .nav-tabs .nav-link {
            border: 1px solid rgba(51, 51, 51, 0.08) !important;
            border-radius: 7px !important;
            background-color: #efefef;
            color: #333333;
            font-size: 0.86rem;
            font-weight: 700;
            line-height: 1;
            margin: 0 !important;
            padding: 0.46rem 0.68rem;
        }

        .event-route-shell .nav-tabs .nav-link.active,
        .event-route-shell .nav-tabs .nav-link:hover,
        .event-route-shell .nav-tabs .nav-link:focus {
            border-color: #fab120 !important;
            background-color: #ffffff;
            color: #333333;
        }

        .event-route-shell .tab-content {
            padding: 0 1rem 1rem;
        }

        .event-theme-shell {
            margin: 0;
            padding: 0;
        }

        @media (max-width: 991.98px) {
            .home-mobile-section {
                margin-top: 0.75rem;
            }
        }

        @media (max-width: 767.98px) {
            .event-action-grid {
                grid-template-columns: 1fr;
            }

            .event-mobile-follow-shell {
                margin-top: 0.5rem;
            }

            .event-mobile-follow-shell .home-side-block:last-child {
                margin-bottom: 0 !important;
            }
        }
    </style>




