    function rrPwaRenderSheet(options = {}) {
      rrPwaCloseSheet();

      const wrapper = document.createElement('div');
      wrapper.id = 'rrPwaSheet';
      wrapper.className = `rr-pwa-sheet${options.centered ? ' is-centered' : ''}`;
