    if (!notice) return;
    function acknowledged() {
        return /(?:^|;\s*)(?:rr_cookie_notice_seen|is-first-visit)=([^;]+)/.test(document.cookie);
    }
    function dismiss() {
        notice.hidden = true;
        document.cookie = 'rr_cookie_notice_seen=1; Max-Age=31536000; Path=/; SameSite=Lax; Secure';
    }
    notice.querySelector('[data-cookie-notice-dismiss]').addEventListener('click', dismiss);
    // Choosing privacy settings is not acceptance or dismissal of any preference.
    notice.querySelector('[data-audience-privacy-open]').addEventListener('click', function (event) {
        notice.hidden = true;
        if (window.RoadRunnersAudiencePrivacy) window.RoadRunnersAudiencePrivacy.open(event);
    });
    window.setTimeout(function () {
        if (!acknowledged()) notice.hidden = false;
    }, 2500);
}());
