    function rrOpenIosInstallInstructions() {
      const i18n = {
        title: 'Install app',
        text: 'On iPhone, install Road Runners from Safari\'s share action.',
        stepShare: 'Tap Safari\'s Share button.',
        stepHome: 'Choose Add to Home Screen.',
        close: 'Close'
      };

      rrPwaRenderSheet({
